    arabic: 'بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ هُوَ اللَّـهُ أَحَدٌ ﴿١﴾ اللَّـهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ ﴿٤﴾',
    transliteration: 'Bismillaahir-Rahmaanir-Raheem. Qul Huwallaahu Ahad. Allaahus-Samad. Lam yalid wa lam yoolad. Wa lam yakul-lahoo kufuwan ahad.',
    translation: {
      en: '(1) Say, "He is Allah, [who is] One, (2) Allah, the Eternal Refuge. (3) He neither begets nor is born, (4) Nor is there to Him any equivalent."',
      dv: 'ﷲ ގެ އިސްމުފުޅުން (ފަށަމެވެ)؛ މާތް ﷲ އީ، ރަޙްމާންވަންތަ، ރަޙީމްވަންތަ ރަސްކަލާނގެއެވެ. (١) ކަލޭގެފާނު ވިދާޅުވާށެވެ! އެއީ ﷲ އެވެ. އެކަލާނގެއީ އެއްކައުވަންތަ ރަސްކަލާނގެއެވެ. (٢) ﷲ އީ، އެންމެހާ ތަކެތި އެކަލާނގެއަށް ބޭނުންތެރިވެގެންވާ، އަދި އެކަލާނގެ އެއްވެސް އެއްޗަކަށް ބޭނުންވެވޮޑިގެންނުވާ ރަސްކަލާނގެއެވެ. (٣) އެކަލާނގެއަކަށް (ދަރިކަލަކު) ލިބިވޮޑިގެނެއްނުވެއެވެ. އަދި އެކަލާނގެ (އެއްވެސް ފަރާތަކުން) އުފަންވެވޮޑިގެނެއްނުވެއެވެ. (٤) އަދި އެކަލާނގެއާ އެއްފަދަވެގެންވާ، ހަމައެކަކުވެސް ނުވެއެވެ.',
    },
